// Normalizes the state for one pick attempt.
//
// Everything the retry loop needs travels in the item JSON, NOT in workflow
// static data. Static data written before the Telegram approval wait is
// discarded when the execution resumes, which is what made rejected articles
// come back and the attempt counter stick at 1.
const inp = $input.first().json || {};

const rejectedLinks = Array.isArray(inp.rejectedLinks) ? inp.rejectedLinks.slice() : [];
const rejectedTitles = Array.isArray(inp.rejectedTitles) ? inp.rejectedTitles.slice() : [];

// Picks completed so far this run. 0 on the first pass (Collect Candidates
// does not set it), then carried forward by Handle Rejection.
const attempt = Number(inp.attempt) || 0;

const all = Array.isArray(inp.candidates) ? inp.candidates : [];
const candidates = all.filter(c => c && c.link && !rejectedLinks.includes(c.link));

if (candidates.length === 0) {
  throw new Error('Loop State got no unrejected candidates. Handle Rejection should have ended the run before reaching the picker.');
}

return [{ json: {
  candidates: candidates,
  candidateCount: candidates.length,
  rejectedLinks: rejectedLinks,
  rejectedTitles: rejectedTitles,
  attempt: attempt,
  usedTopics: Array.isArray(inp.usedTopics) ? inp.usedTopics : [],
} }];

parameters.text:
=Select exactly ONE article for our LinkedIn company news page.

This is pick number {{ $json.attempt + 1 }} of this run.

Candidate articles (JSON). You must choose from this list only:
{{ JSON.stringify($json.candidates) }}

Recently covered topics (avoid anything substantially similar):
{{ JSON.stringify($json.usedTopics) }}

Already rejected by the editor during this run. Never select these, and never select a different article covering the same story:
{{ JSON.stringify($json.rejectedTitles) }}

