// Loop state comes from Loop State via node reference, never from static data:
// static data written before the approval wait is lost when the run resumes.
function fromNode(name) {
  try { return $(name).first(0, $runIndex).json; } catch (e) {}
  try { return $(name).first().json; } catch (e) {}
  return null;
}

const state = fromNode('Loop State') || {};
const candidates = Array.isArray(state.candidates) ? state.candidates : [];
const rejectedLinks = Array.isArray(state.rejectedLinks) ? state.rejectedLinks : [];

if (candidates.length === 0) {
  throw new Error('Select Article received no candidate list from Loop State. Unpin Loop State and Collect Candidates and run the full flow.');
}

const out = ($input.first().json.output) || {};
let picked = out.article;
if (Array.isArray(picked)) picked = picked[0];
picked = picked || {};

let match = candidates.find(c => c.link === picked.link);
if (!match && picked.title) {
  const t = String(picked.title).toLowerCase().trim();
  match = candidates.find(c => String(c.title).toLowerCase().trim() === t);
}

// Hard guard. The model still re-picks a rejected story now and then, and one
// bad pick used to send the loop round on the same article forever.
if (match && rejectedLinks.includes(match.link)) match = null;

// Fall back to the freshest candidate the editor has not already turned down.
if (!match) {
  match = candidates
    .filter(c => !rejectedLinks.includes(c.link))
    .sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate))[0];
}

if (!match) {
  throw new Error('Every remaining candidate has already been rejected this run.');
}

const attempt = (Number(state.attempt) || 0) + 1;

// Still set for Prepare Content, which reads it inside this same pre-approval
// segment where static data is intact.
const sd = $getWorkflowStaticData('global');
sd.currentSelection = { title: match.title, link: match.link };

return [{ json: {
  title: match.title,
  link: match.link,
  isoDate: match.isoDate,
  attempt: attempt,
} }];

const sd = $getWorkflowStaticData('global');

let sel = {};
try { sel = $('Select Article').first(0, $runIndex).json || {}; } catch (e) {}
if (!sel.link) { try { sel = $('Select Article').first().json || {}; } catch (e) {} }
if (!sel.link) sel = sd.currentSelection || {};

const out = ($input.first().json.output) || {};
const post = String(out.post || '').trim();
const headline = String(out.headline || sel.title || '').trim();

// Carry the image query forward so nothing downstream has to reach back
// across the approval wait node to read it off News Reporter.
const imageQuery = String(out.image_query || '').trim() || 'business technology';

if (!post) {
  throw new Error('News Reporter returned an empty post.');
}

// Attempt number comes from Select Article, not sd.attemptCount: static data
// set before the approval wait is discarded on resume, so the counter was
// always reading back as 1.
const attempt = Number(sel.attempt) || 1;

return [{ json: {
  headline: headline,
  post: post,
  imageQuery: imageQuery,
  title: sel.title || '',
  link: sel.link || '',
  attempt: attempt,
} }];

const MAX_ATTEMPTS = 3;

function fromNode(name) {
  try { return $(name).first(0, $runIndex).json; } catch (e) {}
  try { return $(name).first().json; } catch (e) {}
  return null;
}

// Both survive the approval wait because they live in the execution data.
const state = fromNode('Loop State') || {};
const sel = fromNode('Select Article') || {};

const candidates = Array.isArray(state.candidates) ? state.candidates : [];

const rejectedLinks = Array.isArray(state.rejectedLinks) ? state.rejectedLinks.slice() : [];
const rejectedTitles = Array.isArray(state.rejectedTitles) ? state.rejectedTitles.slice() : [];
if (sel.link && !rejectedLinks.includes(sel.link)) rejectedLinks.push(sel.link);
if (sel.title && !rejectedTitles.includes(sel.title)) rejectedTitles.push(sel.title);

const remaining = candidates.filter(c => c && c.link && !rejectedLinks.includes(c.link));
const attempt = Number(sel.attempt) || (Number(state.attempt) || 0) + 1;

// This node runs after the approval wait, so these writes do reach the end of
// the execution and get persisted for future runs.
const sd = $getWorkflowStaticData('global');
const seen = new Set(sd.rejectedLinks || []);
for (const link of rejectedLinks) seen.add(link);
sd.rejectedLinks = Array.from(seen).slice(-100);

if (attempt >= MAX_ATTEMPTS) {
  return [{ json: { retry: false, reason: 'I tried ' + attempt + ' articles this run and none was approved or usable, so I am stopping this run.' } }];
}
if (remaining.length === 0) {
  return [{ json: { retry: false, reason: 'No candidate articles are left to try after the last rejection.' } }];
}

return [{ json: {
  retry: true,
  found: true,
  candidateCount: remaining.length,
  candidates: remaining,
  rejectedLinks: rejectedLinks,
  rejectedTitles: rejectedTitles,
  attempt: attempt,
  usedTopics: Array.isArray(state.usedTopics) ? state.usedTopics : [],
} }];

// The only place cross-run memory is actually persisted. It sits on the
// success output of publishing and after the approval wait, which is the one
// spot where both conditions hold: a post really went out, and static data
// writes survive to the end of the execution.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;

function fromNode(name) {
  try { return $(name).first(0, $runIndex).json; } catch (e) {}
  try { return $(name).first().json; } catch (e) {}
  return null;
}

// sd.currentSelection was written before the wait and does not survive the
// resume, so read the pick back off the node. This is why Notify Published
// used to arrive blank and the topic never reached usedTopics.
const sel = fromNode('Select Article') || {};
const state = fromNode('Loop State') || {};

// Prune here rather than in Clean Memory: Clean Memory runs before the wait,
// so its writes are thrown away and the 7 day expiry never actually ran.
const usedTopics = (sd.usedTopics || [])
  .map(t => typeof t === 'string' ? { title: t, ts: now } : t)
  .filter(t => t && t.title && (now - (t.ts || 0)) < SEVEN_DAYS);

if (sel.title) {
  usedTopics.push({ title: sel.title, ts: now });
}
sd.usedTopics = usedTopics.slice(-50);

// Articles turned down earlier in this run. On the first iteration Handle
// Rejection runs before any wait, so its write was lost. Re-record them here
// so a link that failed extraction is not retried tomorrow.
const rejected = new Set(sd.rejectedLinks || []);
for (const link of (state.rejectedLinks || [])) rejected.add(link);
sd.rejectedLinks = Array.from(rejected).slice(-100);

return [{ json: {
  published: true,
  title: sel.title || '',
  link: sel.link || '',
  attempt: Number(sel.attempt) || 1,
} }];
